import{_ as i,l as n,o as t,c as s,v as e,p as l,x as r,d as h,i as m,S as p}from"./chunks/framework.InCnrqk-.js";const T=JSON.parse('{"title":"突破与均线","description":"","frontmatter":{"title":"突破与均线","date":"2026-09-07T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/breakout-ma.md","filePath":"quant/breakout-ma.md","lastUpdated":1789023840000}'),E={name:"quant/breakout-ma.md"};function d(A,a,c,u,B,_){const o=n("Mermaid");return t(),s("div",null,[a[1]||(a[1]=e('<h1 id="突破与均线" tabindex="-1">突破与均线 <a class="header-anchor" href="#突破与均线" aria-label="Permalink to &quot;突破与均线&quot;">​</a></h1><div class="epigraph"><p>时间序列动量的论文基准是过去超额的符号；期货顾问更常把同一方向写成价格突破前高或站上均线。月频上它们几乎是同一个赌注，日频上换手与误报完全不同。</p><footer>—— 对照 Moskowitz, Ooi &amp; Pedersen, Time Series Momentum, JFE 2012；通道规则见 Donchian 一脉的管理期货实践</footer></div><p><a href="/quant/ts-carry">上一课</a>把期限结构 Carry 写成曲线在价格不变假设下的持有期收益，并要求把商品展期从 TSMOM 里拆开。缺口是 CTA 文档里出现最多的两句话——「突破」和「均线」——看起来像另一类市场。本课把它们写成 TSMOM 的<strong>滤波器实现</strong>：Donchian 通道、双均线、过去超额符号，月频相关高，差异在滞后、换手与假突破。不重讲 roll-down 公式。不要把三条规则的样本内最优当成三个 alpha。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>趋势策略要一个可交易的状态变量：现在算上涨趋势还是下跌趋势。符号函数用累计超额；均线用价格与移动平均的差；突破用价格是否创区间新高或新低。若价格近乎单调，三者同号。若价格在区间里来回穿，均线与通道会反复翻转，符号函数在月频上可能一直为正。问题是度量：<strong>同一信息在不同采样频率与不同非线性下的交易成本与路径依赖</strong>，而不是谁更「技术分析」。</p><p>第二个问题是与风险管理叠在一起。通道常常自带止损（跌回通道则平），均线自带反手。Kaminski 与 Lo 说明止损的期望取决于数据生成过程：趋势上或有益，回归上有害。突破规则把止损写进信号，回测必须把这一非线性与成本一起报告，不能只报方向命中率。</p><h3 id="三种滤波器对应三种滞后" tabindex="-1">三种滤波器对应三种滞后 <a class="header-anchor" href="#三种滤波器对应三种滞后" aria-label="Permalink to &quot;三种滤波器对应三种滞后&quot;">​</a></h3><p>记价格为 \\(P_t\\)。N 日均线交叉大致比较 \\(P_t\\) 与过去窗口的均值；当窗口等于形成期 \\(L\\) 时，它与 \\(\\mathrm{sign}(P_t-P_{t-L})\\) 相关，但在窗口内的路径形状上更平滑。Donchian 通道用 \\(\\max\\{P_{t-1},\\ldots,P_{t-N}\\}\\) 与 \\(\\min\\)，只有极值更新才换状态，对窗口内的回撤不敏感，直到击穿。符号 TSMOM 对形成期内的累计收益敏感，对是否「创新高」不敏感。因此：慢均线少交易、转折慢；短通道多交易、对噪声突破敏感；月频符号最懒。复制应固定 \\(N\\) 或 \\(L\\)，并报告年化换手。</p> \\[s^{\\mathrm{MA}}=\\mathrm{sign}(P_t-\\mathrm{MA}_{L,t}),\\quad s^{\\mathrm{BO}}=\\mathrm{sign}\\bigl(P_t-\\mathrm{High}_{N,t}\\bigr)\\ \\text{或跌破 Low 翻空}. \\]<p><span class="marginnote">「55 日突破」与「12 个月 TSMOM」不是两个市场的独立证据。把参数网格上最大的夏普写成新策略，等于在同一条趋势事实上做多重检验。应预先声明一组工业常用参数，而不是搜索。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>先在同一期货池、同一波动缩放下并排三条规则：12 个月符号、一对常用均线（如 50/200 或 CTA 常用的多组指数均线）、一对常用通道（20/55 一类）。仓位都用 \\(\\sigma_{\\mathrm{tgt}}/\\hat\\sigma\\)。比较：全样本夏普、换手、平均持有期、最大回撤、以及股权危机窗口收益。差异若只出现在换手与危机路径，而方向相关很高，则只能保留一条作为主信号，其余当鲁棒性。</p><p>执行：突破用停损单或收盘确认，要声明是否允许盘中触发。均线常用收盘交叉，避免用未来的当日均线。通道在跳空开盘时可能从缺口外开始，滑点应按跳空后的可成交价，而不是按通道边界的纸面价。国内夜盘与涨跌停会把「突破」变成次日缺口，规则要定义隔夜如何处理。</p><h3 id="假突破是成本-不是过滤器失效那么简单" tabindex="-1">假突破是成本，不是过滤器失效那么简单 <a class="header-anchor" href="#假突破是成本-不是过滤器失效那么简单" aria-label="Permalink to &quot;假突破是成本，不是过滤器失效那么简单&quot;">​</a></h3><p>震荡市里通道会被反复打脸，这是趋势策略的保费：用一段磨损换取能抓住大段单边。用 ATR 过滤、用时间止损、用波动压缩后再突破，都是在买更少的假突破、付出更多的滞后。样本内减少磨损很容易，样本外往往只是把参数挪到另一段震荡。更干净的做法是：接受多尺度组合里短尺度负责转折、长尺度负责少翻，用风险预算限制短尺度的名义，而不是给通道再加第四个确认指标。</p>',15)),(t(),l(p,null,{default:r(()=>[m(o,{id:"mermaid-41",class:"mermaid",graph:"flowchart%20TD%0A%20%20P%5B%22%E4%BB%B7%E6%A0%BC%E8%B7%AF%E5%BE%84%22%5D%20--%3E%20SIG%5B%22%E7%AC%A6%E5%8F%B7%20TSMOM%22%5D%0A%20%20P%20--%3E%20MA%5B%22%E5%9D%87%E7%BA%BF%E4%BA%A4%E5%8F%89%22%5D%0A%20%20P%20--%3E%20BO%5B%22%E9%80%9A%E9%81%93%E7%AA%81%E7%A0%B4%22%5D%0A%20%20SIG%20--%3E%20CMP%5B%22%E5%90%8C%E6%B1%A0%E3%80%81%E5%90%8C%E6%B3%A2%E5%8A%A8%E7%BC%A9%E6%94%BE%22%5D%0A%20%20MA%20--%3E%20CMP%0A%20%20BO%20--%3E%20CMP%0A%20%20CMP%20--%3E%20TO%5B%22%E6%8D%A2%E6%89%8B%20%2F%20%E6%BB%9E%E5%90%8E%20%2F%20%E5%8D%B1%E6%9C%BA%E8%B7%AF%E5%BE%84%22%5D%0A%20%20TO%20--%3E%20KEEP%5B%22%E4%BF%9D%E7%95%99%E4%B8%80%E6%9D%A1%E4%B8%BB%E4%BF%A1%E5%8F%B7%20%2B%20%E9%B2%81%E6%A3%92%E6%80%A7%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[h(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=e('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>信息缓慢进入价格时，任何「追已实现方向」的滤波器都能分到趋势溢价。通道对极值敏感，更像止损反手的趋势跟踪；均线对平均水平敏感，更像低通滤波；符号对积分收益敏感，更接近 MOP 的可检验定义。套保压力与资金流不区分你用的是均线还是通道——它们只看到期货净持仓。因此机制检验应落在资产池与波动缩放上，而不是落在均线窗口是否为 19 还是 21。</p><p>震荡磨损的机制是均值回归成分：短期反向、区间交易、或政策把价格钉在区间。这时突破的期望为负，与 Kaminski–Lo 在回归 DGP 上对止损的警告同构。市场状态不可完美观测，CTA 用多时间尺度分散这种误设，而不是声称能识别「这是震荡」。</p><h3 id="仓位单位与突破次数" tabindex="-1">仓位单位与突破次数 <a class="header-anchor" href="#仓位单位与突破次数" aria-label="Permalink to &quot;仓位单位与突破次数&quot;">​</a></h3><p>海龟规则把一笔突破的名义与 ATR 挂钩，本质是<a href="/quant/vol-scale-cta">波动缩放</a>。没有这一层，短通道在高波商品上会主导组合。突破次数（金字塔加仓）会把趋势的凸性加强，也会把回撤加强：加仓发生在已经走出来的路径上，反手时所有单位一起停。回测必须按单位记账，并禁止用同一突破在样本内加无限金字塔。风控上，通道止损与组合 kill switch 不要设成同一价格，否则同业拥挤时你与说明书上的止损一起成为供给。</p><p><span class="marginnote">均线金叉在股票软件里的流行度，不构成期货 CTA 的样本外证据。MOP 的对象是流动期货超额收益；把指数的均线规则套到含涨跌停的个股，空头腿与成交假设都变了。</span></p><h2 id="边界与工程取舍" tabindex="-1">边界与工程取舍 <a class="header-anchor" href="#边界与工程取舍" aria-label="Permalink to &quot;边界与工程取舍&quot;">​</a></h2><p>不要把突破写成与 TSMOM 正交的第二利润源，除非正交检验过关。不要用未扣滑点的盘中最高最低来算通道命中。不要在已经多尺度均线之后再叠一层同向的 12 个月符号而不降杠杆。参数应来自业界常用集合与论文主设定，网格搜索要做折扣。A 股与国内商品的限价、夜盘与交割月规则会改变「前高」的定义，不能直接用 CME 的 N。</p><p>与<a href="/quant/cta-tsmom">时间序列动量 CTA</a> 的分工：那一篇管产品结构与 Moskowitz 定义；本篇管滤波器之间的可替代性。与危机 alpha 的关系：慢均线在急跌里更慢，可能先亏后翻空；短通道更快，但也更容易在 V 型里连续假突破。报告危机窗口时应分快慢尺度，而不是只给一个混合 CTA。</p><p><span class="marginnote">出处：Moskowitz, Ooi &amp; Pedersen, <em>Time Series Momentum</em>, JFE, 2012。通道与单位仓位属于 Donchian / 海龟一脉的实践传统，不是 2012 年论文的定义。止损与 DGP 见 Kaminski and Lo, Journal of Financial Markets, 2014。长样本趋势见 Hurst, Ooi &amp; Pedersen。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>突破、均线与过去超额符号是同一趋势赌注的三种滤波器，月频相关高，差异在换手、滞后与假突破。</li><li>比较必须在同一资产池与同一波动缩放下进行；胜出的若只是换手不同，不应宣称新 alpha。</li><li>通道自带止损，期望依赖趋势还是回归的 DGP；震荡磨损是保费。</li><li>金字塔加仓放大凸性也放大拥挤减仓；ATR 单位是波动缩放，不是突破本身的信息。</li><li>出处：Moskowitz et al., 2012；Donchian 式通道实践；Kaminski–Lo, 2014。</li></ul>',12))])}const M=i(E,[["render",d]]);export{T as __pageData,M as default};
